import express from 'express';

const app = express();
app.use(express.json());

let books = [
  { id: 1, title: 'Clean Code', author: 'Robert Martin' },
  { id: 2, title: 'Eloquent JavaScript', author: 'Marijn Haverbeke' },
];
let nextId = 3;

app.get('/api/books', (req, res) => {
  res.json(books);
});

app.get('/api/books/:id', (req, res) => {
  const book = books.find((b) => b.id === Number(req.params.id));
  if (!book) return res.status(404).json({ error: 'Book not found' });
  res.json(book);
});

app.post('/api/books', (req, res) => {
  const { title, author } = req.body;
  if (!title || !author) {
    return res.status(400).json({ error: 'title and author are required' });
  }
  const book = { id: nextId++, title, author };
  books.push(book);
  res.status(201).json(book);
});

app.put('/api/books/:id', (req, res) => {
  const book = books.find((b) => b.id === Number(req.params.id));
  if (!book) return res.status(404).json({ error: 'Book not found' });
  book.title = req.body.title ?? book.title;
  book.author = req.body.author ?? book.author;
  res.json(book);
});

app.delete('/api/books/:id', (req, res) => {
  const before = books.length;
  books = books.filter((b) => b.id !== Number(req.params.id));
  if (books.length === before) return res.status(404).json({ error: 'Book not found' });
  res.status(204).end();
});

app.listen(3000, () => console.log('Books API on port 3000'));

